'use strict';
(() => {
const C=CPARS,$=s=>document.querySelector(s),E=C.esc;
const KEY='cpars-coordination-tracker-v1';
const defaults=()=>({version:2,contracts:[],evaluations:[],outreach:[],assignments:[],actions:[],reviews:[],subfactors:[],settings:C.defaultSettings()});
let state=defaults(),selected='',filter='',reportKind='summary',pendingImport=null,saveTimer,dialogReturnFocus='',messageTimer;
const schema={
 contract:[['contractNumber','Contract number','text',true],['orderNumber','Task or delivery order number'],['parentContract','Parent contract reference'],['reportingLevel','CPARS reporting level','select:Pending Verification|Contract|Order'],['nickname','Nickname'],['agency','Customer agency'],['office','Contracting office'],['contractType','Contract type'],['popStart','Performance start','date'],['popEnd','Performance end','date'],['actualCompletion','Actual completion','date'],['representative','Contracts representative'],['manager','Program Manager'],['governmentContacts','Government contacts / references','textarea'],['registration','CPARS registration status','select:Unknown|Registered|Pending|Not registered'],['applicability','Applicability','select:Pending Verification|Applicable|Not Applicable'],['applicabilityRationale','Applicability rationale','textarea'],['notes','General notes','textarea'],['archived','Archived','checkbox']],
 evaluation:[['type','Evaluation type','select:Annual|Interim|Final'],['periodStart','Evaluation period start','date',true],['periodEnd','Evaluation period end','date',true],['expectedAvailability','Expected availability (planning date)','date'],['reportingDeadline','Government completion target (CPARS guidance or override)','date'],['deadlineAuthority','Deadline authority / override rationale'],['notificationDate','Actual CPARS notification','date'],['commentDeadline','Official CPARS comment deadline / correction','date'],['commentDeadlineNote','Deadline correction rationale'],['internalTarget','Internal response target','date'],['governmentStatus','Government evaluation status','select:Expected|Awaiting Evaluation|Available for Comment|Awaiting Government Finalization|Finalized'],['outreachStatus','Outreach status','select:Not Started|Planned|Sent|Awaiting Government Response|Response Received|Complete'],['readiness','Departmental readiness','select:Not Started|Requested|In Progress|Ready|Not Applicable'],['responseStatus','Contractor coordination status','select:Not Started|Preparing|Awaiting Departmental Inputs|Under Internal Review|Ready for Submission|Submitted|No Comments Required|Complete'],['postStatus','Post-evaluation status','select:Not Started|Open|In Progress|Complete|Not Applicable'],['representative','Responsible Contracts representative'],['concurrence','Contractor position','select:Not sure|Concur|Do Not Concur'],['responseText','Consolidated contractor comments (editable)','textarea'],['submissionDate','Response submission date','date'],['submissionReference','Submission confirmation reference'],['finalizationDate','Government finalization date','date'],['reviewingOfficial','Reviewing Official involvement'],['disposition','Comment disposition / unresolved disagreement','textarea'],['notes','Supporting notes','textarea'],['archived','Archived','checkbox']],
 outreach:[['date','Outreach date','date',true],['representative','Contracts representative'],['recipient','Government recipient'],['method','Method','select:Email|Phone|Meeting|Other'],['purpose','Purpose','select:Confirm evaluation timing|Confirm evaluator|Request evaluation status|Provide authorized performance inputs|Follow up on delay|Request clarification|Confirm finalization|Other'],['summary','Summary','textarea'],['response','Government response','textarea'],['commitments','Commitments / expected actions','textarea'],['reference','Supporting reference'],['nextDate','Next follow-up','date']],
 assignment:[['phase','Phase','select:Before CPARS|During CPARS|After CPARS'],['factor','Evaluation factor','select:General|Technical/Quality|Cost Control|Schedule/Timeliness|Management/Business Relations|Small Business Subcontracting|Other'],['department','Department','text',true],['owner','Responsible individual'],['request','Requested contribution','textarea'],['assignedDate','Assignment date','date'],['dueDate','Due date','date'],['status','Status','select:Not Started|Requested|In Progress|Complete|Not Applicable'],['summary','Response summary','textarea'],['evidence','Evidence reference'],['issues','Outstanding issues','textarea'],['completedDate','Completion date','date'],['review','Contracts review','select:Not Reviewed|Reviewed|Changes Requested|Not Applicable']],
 action:[['issue','Issue / improvement action','textarea',true],['department','Responsible department'],['owner','Responsible individual'],['targetDate','Target completion','date'],['status','Status','select:Open|In Progress|Complete|Not Applicable'],['evidence','Evidence reference'],['completedDate','Completion date','date'],['effectiveness','Effectiveness review','textarea']],
 review:[['phase','Review phase','select:Before CPARS|During CPARS|After CPARS'],['role','Reviewer role','select:Contracts|Program Management|Legal|Leadership|Other'],['reviewer','Reviewer name or role','text',true],['status','Review status','select:Requested|In Progress|Changes Requested|Concur|Do Not Concur|Complete'],['date','Review date','date'],['notes','Review notes','textarea']],
 subfactor:[['factor','Parent evaluation factor','select:Technical/Quality|Cost Control|Schedule/Timeliness|Management/Business Relations|Small Business Subcontracting|Other'],['name','Subfactor name','text',true],['applicable','Applicable','select:Not sure|Yes|No'],['preSummary','Pre-evaluation performance facts','textarea'],['governmentText','Government narrative / assertion','textarea'],['initialRating','Initial Government rating','select:Not recorded|Exceptional|Very Good|Satisfactory|Marginal|Unsatisfactory|Not Applicable'],['finalRating','Final Government rating','select:Not recorded|Exceptional|Very Good|Satisfactory|Marginal|Unsatisfactory|Not Applicable'],['factStatus','Fact status','select:Not sure|Verified fact|Unsupported assertion|Disputed statement|Outstanding question|Corrective action taken|Commitment pending approval'],['position','Contractor position / proposed response','textarea'],['evidence','Evidence / contractual references','textarea'],['review','Requested resolution / reviewer feedback','textarea']]
};
const collections={contract:'contracts',evaluation:'evaluations',outreach:'outreach',assignment:'assignments',action:'actions',review:'reviews',subfactor:'subfactors'};
function dbOpen(){return new Promise((resolve,reject)=>{const r=indexedDB.open(KEY,1);r.onupgradeneeded=()=>r.result.createObjectStore('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function load(){try{const db=await dbOpen();const found=await new Promise((resolve,reject)=>{const t=db.transaction('workspace');const r=t.objectStore('workspace').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});db.close();if(found)state=C.normalizeState(found);}catch(e){message('Local storage unavailable: '+e.message);}}
async function persist(){try{const db=await dbOpen();await new Promise((resolve,reject)=>{const t=db.transaction('workspace','readwrite');t.objectStore('workspace').put(state,'state');t.oncomplete=resolve;t.onerror=()=>reject(t.error);});db.close();}catch(e){message('Save failed: '+e.message);}}
function save(){syncStatuses();clearTimeout(saveTimer);saveTimer=setTimeout(persist,100);render();}
function message(s){clearTimeout(messageTimer);$('#message').textContent=s;if(s&&!/failed|unavailable/i.test(s))messageTimer=setTimeout(()=>{$('#message').textContent='';},6000);}
function link(view,label,number){return `<a href="#${view}" ${current()===view?'aria-current="page"':''}><span class="step">${number}</span>${label}</a>`;}
function nav(){const names=[['dashboard','Dashboard'],['contracts','Contracts'],['evaluations','Evaluations'],['outreach','Government outreach'],['departments','Departments'],['reports','Reports & data'],['settings','Settings & guide']];$('#nav').innerHTML=names.map((x,i)=>link(x[0],x[1],i+1)).join('');}
function current(){return location.hash.slice(1).split(/[/?]/)[0]||'dashboard';}
function contract(id){return state.contracts.find(x=>x.id===id);}
function evaluation(id=selected){return state.evaluations.find(x=>x.id===id);}
function cname(c){return [c?.contractNumber,c?.orderNumber].filter(Boolean).join(' / ')||'Unknown contract';}
function ename(e){return `${cname(contract(e.contractId))} · ${e.type} · ${e.periodEnd||'period not set'}`;}
function phase(e){if(e.finalizationDate||e.governmentStatus==='Finalized')return 'After CPARS';if(e.notificationDate)return 'During CPARS';return 'Before CPARS';}
function phaseTab(e){return phase(e)==='After CPARS'?'after':phase(e)==='During CPARS'?'during':'before';}
function syncStatuses(){for(const e of state.evaluations){const outreach=state.outreach.filter(x=>x.evaluationId===e.id),assignments=state.assignments.filter(x=>x.evaluationId===e.id),actions=state.actions.filter(x=>x.evaluationId===e.id);if(e.finalizationDate)e.governmentStatus='Finalized';else if(e.submissionDate)e.governmentStatus='Awaiting Government Finalization';else if(e.notificationDate&&['Expected','Awaiting Evaluation','Awaiting Government Finalization','Finalized'].includes(e.governmentStatus))e.governmentStatus='Available for Comment';if(e.submissionDate&&['Not Started','Preparing','Awaiting Departmental Inputs','Under Internal Review','Ready for Submission'].includes(e.responseStatus))e.responseStatus='Submitted';if(outreach.length){if(outreach.some(x=>x.response)&&e.outreachStatus!=='Complete')e.outreachStatus='Response Received';else if(['Not Started','Planned'].includes(e.outreachStatus))e.outreachStatus='Sent';}if(assignments.length){const open=assignments.filter(x=>!['Complete','Not Applicable'].includes(x.status));e.readiness=open.length?(assignments.some(x=>x.status==='In Progress'||x.status==='Complete')?'In Progress':'Requested'):assignments.every(x=>x.status==='Not Applicable')?'Not Applicable':'Ready';}if(actions.length){const open=actions.filter(x=>!['Complete','Not Applicable'].includes(x.status));e.postStatus=open.length?(open.some(x=>x.status==='In Progress')?'In Progress':'Open'):actions.every(x=>x.status==='Not Applicable')?'Not Applicable':'Complete';}}}
function active(e){return !e.archived&&!contract(e.contractId)?.archived&&contract(e.contractId)?.applicability==='Applicable';}
function due(date){const n=C.diffDays(C.today(),date);return n===null?'No date':n<0?`${-n} days past target`:n===0?'Due today':`${n} days remaining`;}
function chip(text,tone='info'){return `<span class="pill ${tone}">${E(text)}</span>`;}
function head(title,subtitle,button=''){return `<div class="heading"><div><h1>${E(title)}</h1><p class="hint">${E(subtitle)}</p></div>${button}</div>`;}
function table(headers,rows){
  const labeled=rows?.replace(/<tr([^>]*)>([\s\S]*?)<\/tr>/g,(_,attrs,body)=>{let n=0;return `<tr${attrs}>${body.replace(/<td([^>]*)>/g,(cell,cellAttrs)=>`<td${cellAttrs} data-label="${E(headers[n++]||'')}">`)}</tr>`;});
  return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th scope="col">${E(x)}</th>`).join('')}</tr></thead><tbody>${labeled||`<tr><td colspan="${headers.length}" class="empty">No records yet.</td></tr>`}</tbody></table></div>`;
}
function selectOptions(items,currentValue){return items.map(x=>`<option value="${E(x)}" ${x===currentValue?'selected':''}>${E(x)}</option>`).join('');}
function filters(){return `<div class="filters"><label>Search<input id="search" type="search" value="${E(filter)}" placeholder="Contract, agency, owner, status"></label><label>Responsible representative<select id="rep-filter"><option value="">All representatives</option>${[...new Set(state.contracts.map(c=>c.representative).filter(Boolean))].sort().map(x=>`<option ${x===repFilter?'selected':''}>${E(x)}</option>`).join('')}</select></label></div>`;}
let repFilter='';
function match(e){const c=contract(e.contractId)||{};return (!repFilter||c.representative===repFilter||e.representative===repFilter)&&[c.contractNumber,c.orderNumber,c.nickname,c.agency,c.representative,c.manager,e.type,e.governmentStatus,e.responseStatus,phase(e)].join(' ').toLowerCase().includes(filter.toLowerCase());}
const dash={manager:'',agency:'',phase:'',type:'',applicability:'',proximity:'',outreach:'',coordination:''};
function dashboardMatch(e){const c=contract(e.contractId)||{},d=dash,today=C.today();if(!match(e)||d.manager&&c.manager!==d.manager||d.agency&&c.agency!==d.agency||d.phase&&phase(e)!==d.phase||d.type&&e.type!==d.type||d.applicability&&c.applicability!==d.applicability||d.outreach&&e.outreachStatus!==d.outreach||d.coordination&&e.responseStatus!==d.coordination)return false;if(d.proximity){const date=e.notificationDate&&!e.submissionDate?e.commentDeadline:e.expectedAvailability||e.reportingDeadline,days=C.diffDays(today,date);if(days===null||(d.proximity==='overdue'?days>=0:days<0||days>Number(d.proximity)))return false;}return true;}
function dashboardFilterControls(){const choices=(key,label,values)=>`<label>${label}<select data-dashboard-filter="${key}"><option value="">All</option>${values.filter(Boolean).map(v=>`<option value="${E(v)}" ${dash[key]===v?'selected':''}>${E(v)}</option>`).join('')}</select></label>`;return `<div class="dashboard-filter-grid">${filters()}${choices('manager','Program Manager',[...new Set(state.contracts.map(c=>c.manager))].sort())}${choices('agency','Customer agency',[...new Set(state.contracts.map(c=>c.agency))].sort())}${choices('phase','Evaluation phase',['Before CPARS','During CPARS','After CPARS'])}${choices('type','Evaluation type',['Annual','Interim','Final'])}${choices('applicability','Applicability',['Applicable','Pending Verification','Not Applicable'])}${choices('proximity','Deadline proximity',['7','14','30','overdue'])}${choices('outreach','Outreach status',['Not Started','Planned','Sent','Awaiting Government Response','Response Received','Complete'])}${choices('coordination','Contractor coordination',['Not Started','Preparing','Awaiting Departmental Inputs','Under Internal Review','Ready for Submission','Submitted','No Comments Required','Complete'])}</div>`;}
function metric(){return new URLSearchParams(location.hash.split('?')[1]||'').get('metric')||'';}
function needsOutreach(e){return !e.notificationDate&&e.periodEnd>=C.today()&&C.addDays(e.periodEnd,-Number(state.settings.advanceDays))<=C.today()&&!state.outreach.some(o=>o.evaluationId===e.id);}
function metricMatch(e,key){const today=C.today(),warning=C.addDays(today,state.settings.warningDays);return key==='outreachNeeded'?needsOutreach(e):key==='outstandingGov'?['Sent','Awaiting Government Response'].includes(e.outreachStatus):key==='approachingComment'?!!e.notificationDate&&!e.submissionDate&&!e.finalizationDate&&!!e.commentDeadline&&e.commentDeadline>=today&&e.commentDeadline<=warning:key==='pastExpected'?!e.notificationDate&&!!e.expectedAvailability&&e.expectedAvailability<today:key==='pastTarget'?!e.finalizationDate&&!!e.reportingDeadline&&e.reportingDeadline<today:key==='comment'?!!e.notificationDate&&!e.submissionDate&&!e.finalizationDate:key==='upcoming'?!e.notificationDate&&e.periodEnd>=today:key==='awaiting'?!!e.submissionDate&&!e.finalizationDate:key==='completed'?!!e.finalizationDate:true;}
function metricBanner(view,label){return metric()?`<p class="metric-banner">Showing ${E(label)} · <a href="#${view}">Clear dashboard filter</a></p>`:'';}
function dashboardContracts(evals){const evalFiltersActive=['phase','type','proximity','outreach','coordination'].some(k=>dash[k]),visibleIds=new Set(evals.map(e=>e.contractId));return state.contracts.filter(c=>!c.archived&&(!evalFiltersActive||visibleIds.has(c.id))&&(!dash.manager||c.manager===dash.manager)&&(!dash.agency||c.agency===dash.agency)&&(!dash.applicability||c.applicability===dash.applicability)&&(!repFilter||c.representative===repFilter)&&[c.contractNumber,c.orderNumber,c.nickname,c.agency,c.representative,c.manager,c.applicability].join(' ').toLowerCase().includes(filter.toLowerCase()));}
function dashboard(){
  const a=state.evaluations.filter(e=>active(e)&&dashboardMatch(e)),today=C.today(),warning=C.addDays(today,state.settings.warningDays);const visibleContracts=dashboardContracts(a);
  const openAssignments=state.assignments.filter(x=>!['Complete','Not Applicable'].includes(x.status)&&a.some(e=>e.id===x.evaluationId));
  const openActions=state.actions.filter(x=>!['Complete','Not Applicable'].includes(x.status)&&a.some(e=>e.id===x.evaluationId));
  const counts={outreachNeeded:a.filter(needsOutreach).length,outstandingGov:a.filter(e=>['Sent','Awaiting Government Response'].includes(e.outreachStatus)).length,approachingComment:a.filter(e=>metricMatch(e,'approachingComment')).length,overdueActions:openActions.filter(x=>x.targetDate&&x.targetDate<today).length,contracts:visibleContracts.length,applicable:visibleContracts.filter(x=>x.applicability==='Applicable').length,pending:visibleContracts.filter(x=>x.applicability==='Pending Verification').length,upcoming:a.filter(e=>!e.notificationDate&&e.periodEnd>=today).length,pastExpected:a.filter(e=>!e.notificationDate&&e.expectedAvailability&&e.expectedAvailability<today).length,pastTarget:a.filter(e=>!e.finalizationDate&&e.reportingDeadline&&e.reportingDeadline<today).length,comment:a.filter(e=>e.notificationDate&&!e.submissionDate&&!e.finalizationDate).length,awaiting:a.filter(e=>e.submissionDate&&!e.finalizationDate).length,completed:a.filter(e=>e.finalizationDate).length,actions:openActions.length,followups:state.outreach.filter(o=>a.some(e=>e.id===o.evaluationId)&&o.nextDate&&o.nextDate<=today).length};
  const queue=[];
  for(const e of a.filter(match)){
    const c=contract(e.contractId)||{};
    if(needsOutreach(e))queue.push({e,date:C.addDays(e.periodEnd,-Number(state.settings.advanceDays)),action:'Begin proactive Government outreach',owner:c.representative});
    if(!e.notificationDate&&e.expectedAvailability&&e.expectedAvailability<=warning)queue.push({e,date:e.expectedAvailability,action:state.outreach.some(o=>o.evaluationId===e.id)?'Check delayed Government evaluation':'Check expected availability and record outreach',owner:c.representative});
    if(e.notificationDate&&!e.submissionDate&&!e.finalizationDate)queue.push({e,date:e.commentDeadline||C.suggestedDates(e,state.settings).commentDeadline,action:'Coordinate contractor response',owner:e.representative||c.representative});
    if(e.submissionDate&&!e.finalizationDate)queue.push({e,date:e.reportingDeadline,action:'Follow up on Government finalization',owner:e.representative||c.representative});
  }
  for(const x of openAssignments.filter(x=>x.dueDate&&x.dueDate<=warning)){const e=evaluation(x.evaluationId);if(e&&a.includes(e))queue.push({e,date:x.dueDate,action:`Department input: ${x.department}`,owner:x.owner||x.department});}
  for(const o of state.outreach.filter(o=>o.nextDate&&o.nextDate<=warning)){const e=evaluation(o.evaluationId);if(e&&a.includes(e))queue.push({e,date:o.nextDate,action:'Government outreach follow-up',owner:o.representative||e.representative||contract(e.contractId)?.representative});}
  for(const x of openActions.filter(x=>x.targetDate&&x.targetDate<=warning)){const e=evaluation(x.evaluationId);if(e&&a.includes(e))queue.push({e,date:x.targetDate,action:`Improvement action: ${x.issue}`,owner:x.owner||x.department});}
  queue.sort((x,y)=>(x.date||'9999').localeCompare(y.date||'9999'));
  const next=a.filter(e=>!e.finalizationDate&&e.periodEnd>=today).sort((x,y)=>x.periodEnd.localeCompare(y.periodEnd))[0];
  const hero=`<section class="dashboard-hero"><div><p class="eyebrow">Portfolio overview <span aria-hidden="true">·</span> ${E(today)}</p><h1>Portfolio dashboard</h1><p>Track what needs attention across evaluations, responses, and improvement actions.</p></div><div class="hero-actions">${counts.contracts?`<button class="primary" data-new="contract">Add contract</button><a href="#evaluations">View evaluations <span aria-hidden="true">→</span></a>`:`<a href="#settings">Read the guide <span aria-hidden="true">→</span></a>`}</div></section>`;
  if(!state.contracts.length)return hero+`<section class="welcome-panel"><div><p class="eyebrow">Get started</p><h2>Build your portfolio</h2><p>Add a contract or order, confirm applicability, then review its suggested evaluation periods.</p><button class="primary" data-new="contract">Add your first contract</button></div><ol class="welcome-steps"><li><strong>01</strong><span>Set up contracts and orders</span></li><li><strong>02</strong><span>Confirm evaluation periods</span></li><li><strong>03</strong><span>Track outreach and responses</span></li></ol></section>`;
  const highlights=[['Active comment windows',counts.comment,'evaluations','comment',counts.comment?'warning':'neutral'],['Upcoming evaluations',counts.upcoming,'evaluations','upcoming','neutral'],['Awaiting finalization',counts.awaiting,'evaluations','awaiting','neutral'],['Open improvement actions',counts.actions,'departments','actions',counts.actions?'warning':'neutral']];
  const highlightsHtml=`<div class="section-heading highlights-heading"><div><p class="eyebrow">Overview</p><h2>Key counts</h2></div></div><section class="dashboard-highlights" aria-label="Portfolio highlights">${highlights.map(([label,value,to,key,tone])=>`<a class="highlight ${tone}" href="#${to}?metric=${key}"><span>${E(label)}</span><strong>${value}</strong><span class="highlight-link">Browse ${to==='departments'?'actions':'evaluations'} →</span></a>`).join('')}</section>`;
  const queueHtml=queue.length?`<div class="action-list">${queue.map(q=>{const days=C.diffDays(today,q.date);const tone=days!==null&&days<0?'danger':days===0?'warning':'info';return `<article class="action-row"><div class="action-date ${tone}"><strong>${E(due(q.date))}</strong><span>${E(q.date||'No date')}</span></div><div class="action-content"><button class="link action-title" data-open="${E(q.e.id)}">${E(q.action)}</button><p>${E(ename(q.e))} <span aria-hidden="true">·</span> ${E(phase(q.e))} <span aria-hidden="true">·</span> ${E(q.owner||'Unassigned')}</p></div><button class="action-arrow" data-open="${E(q.e.id)}" aria-label="Open ${E(ename(q.e))}">→</button></article>`;}).join('')}</div>`:`<div class="quiet-state"><strong>No dated actions in the warning window</strong><p>Unscheduled work may still need review. Check evaluations and department assignments regularly.</p></div>`;
  const indicators=[['All contracts / orders',counts.contracts,'contracts','all'],['Applicable',counts.applicable,'contracts','applicable'],['Pending verification',counts.pending,'contracts','pending'],['Outreach needed',counts.outreachNeeded,'evaluations','outreachNeeded'],['Government responses outstanding',counts.outstandingGov,'evaluations','outstandingGov'],['Comment deadlines approaching',counts.approachingComment,'evaluations','approachingComment'],['Past expected availability',counts.pastExpected,'evaluations','pastExpected'],['Past guidance target',counts.pastTarget,'evaluations','pastTarget'],['Outreach follow-ups due',counts.followups,'outreach','followups'],['Overdue improvement actions',counts.overdueActions,'departments','overdueActions'],['Completed evaluations',counts.completed,'evaluations','completed']];
  return hero+`<div class="dashboard-columns"><section class="panel attention-panel"><div class="section-heading"><div><p class="eyebrow">Work queue</p><h2>Needs attention</h2></div><span class="section-count">${queue.length} dated ${queue.length===1?'item':'items'}</span></div><details class="queue-filters" ${filter||repFilter||Object.values(dash).some(Boolean)?'open':''}><summary>Filter dashboard</summary>${dashboardFilterControls()}</details>${queueHtml}</section><aside class="dashboard-aside"><section class="panel"><div class="section-heading"><div><p class="eyebrow">Portfolio</p><h2>At a glance</h2></div></div><div class="indicator-list">${indicators.map(([label,n,to,key])=>`<a href="#${to}?metric=${key}"><span>${E(label)}</span><strong>${n}</strong></a>`).join('')}</div></section>${next?`<section class="panel next-panel"><p class="eyebrow">Coming up</p><h2>Next evaluation period</h2><p class="next-name">${E(ename(next))}</p><p>${E(next.periodStart)} to ${E(next.periodEnd)}</p><button class="link" data-open="${E(next.id)}">Open evaluation →</button></section>`:''}</aside></div>`+highlightsHtml+`<p class="dashboard-footnote">Dates and indicators update while the app is open. Confirm official CPARS dates before acting.</p>`;
}
function contracts(){let list=(metric()?dashboardContracts(state.evaluations.filter(e=>active(e)&&dashboardMatch(e))):state.contracts).filter(c=>(!metric()||metric()==='all'||metric()==='applicable'&&c.applicability==='Applicable'||metric()==='pending'&&c.applicability==='Pending Verification')&&[c.contractNumber,c.orderNumber,c.nickname,c.agency,c.representative,c.manager,c.applicability].join(' ').toLowerCase().includes(filter.toLowerCase())&&(!repFilter||c.representative===repFilter));return head('Contract inventory','Confirm CPARS applicability and the contract or order reporting level.',`<button class="primary" data-new="contract">Add contract</button>`)+`<div class="panel">${filters()}${metricBanner('contracts',metric()==='applicable'?'applicable contracts':metric()==='pending'?'pending verification':'all contracts')}${table(['Contract / order','Agency / office','Performance','Applicability','Representative','Actions'],list.map(c=>`<tr><td><strong>${E(cname(c))}</strong><br>${E(c.nickname)}</td><td>${E(c.agency)}<br>${E(c.office)}</td><td>${E(c.popStart)} to ${E(c.popEnd)}</td><td>${chip(c.applicability||'Pending Verification',c.applicability==='Applicable'?'success':c.applicability==='Not Applicable'?'info':'warning')}${c.archived?' '+chip('Archived','warning'):''}</td><td>${E(c.representative)}</td><td><button data-edit="contract:${E(c.id)}">Edit</button> <button data-cycle="${E(c.id)}">Review cycles</button></td></tr>`).join(''))}</div>`;}
function evaluations(){const list=state.evaluations.filter(e=>(metric()?active(e)&&dashboardMatch(e):match(e))&&metricMatch(e,metric())).sort((a,b)=>(a.periodEnd||'').localeCompare(b.periodEnd||''));return head('Evaluation coordination','Annual cycles follow performance periods. Confirm each schedule before using it.',`<button class="primary" data-new="evaluation">Add evaluation</button>`)+`<div class="panel">${filters()}${metricBanner('evaluations',metric())}${table(['Evaluation','Phase','Government status','Contractor activity','Key dates','Actions'],list.map(e=>`<tr><td><button class="link" data-open="${E(e.id)}">${E(ename(e))}</button>${e.archived?' '+chip('Archived','warning'):''}</td><td>${chip(phase(e))}</td><td>${E(e.governmentStatus||'Expected')}</td><td>${E(e.responseStatus||'Not Started')}</td><td>Expected: ${E(e.expectedAvailability||'—')}<br>Comment: ${E(e.commentDeadline||'—')}<br>Government: ${E(e.reportingDeadline||'—')}</td><td><button data-edit="evaluation:${E(e.id)}">Edit</button></td></tr>`).join(''))}</div>`;}
function detail(){const e=evaluation();if(!e)return evaluations();const c=contract(e.contractId),suggested=C.suggestedDates(e,state.settings),days=e.notificationDate?due(e.commentDeadline||suggested.commentDeadline):'Starts after actual notification';const assignments=state.assignments.filter(x=>x.evaluationId===e.id),outreach=state.outreach.filter(x=>x.evaluationId===e.id),actions=state.actions.filter(x=>x.evaluationId===e.id);const tab=location.hash.split('/')[2]||'before';const before=`<div class="panel"><h2>Preparation</h2><p>Expected availability: ${E(e.expectedAvailability||suggested.expectedAvailability||'Unscheduled')} (internal planning). CPARS guidance completion target: ${E(e.reportingDeadline||suggested.reportingDeadline||'Unscheduled')}.</p><p>Outreach target: ${E(e.periodEnd?C.addDays(e.periodEnd,-Number(state.settings.advanceDays)):'Unscheduled')} (internal). Proactive outreach and pre-evaluation narratives are optional internal practices.</p><div class="actions"><button data-new="outreach" class="primary">Record Government outreach</button><button data-new="assignment">Request department input</button></div></div><div class="panel"><h2>Performance summary worksheet</h2>${factorEditor(e,'pre')}</div>`;
const during=`<div class="panel"><h2>Response countdown</h2><p>${chip(days,e.notificationDate&&C.diffDays(C.today(),e.commentDeadline||suggested.commentDeadline)<0?'danger':'warning')}</p><p>FAR 42.1503(d): up to 14 calendar days from actual CPARS notification. Confirm the deadline in CPARS. Later comments may still be recorded under FAR 42.1503(f), subject to the official system's process.</p><p>Internal target: ${E(e.internalTarget||suggested.internalTarget||'Not set')}. Outstanding inputs: ${assignments.filter(x=>x.status!=='Complete'&&x.status!=='Not Applicable').length}.</p><button data-edit="evaluation:${E(e.id)}" class="primary">Update notification, status, or response</button></div><div class="panel"><h2>Evaluation factor review</h2><p class="hint">Record Government assertions, your position, references, evidence, and proposed response. Ratings require user judgment.</p>${factorEditor(e,'during')}</div><div class="panel"><h2>Contractor comments</h2><p class="hint">Copy or print for internal review and authorized submission in official CPARS. No automatic submission.</p><textarea id="response-text" aria-label="Consolidated contractor comments">${E(e.responseText)}</textarea><div class="actions"><button id="build-response">Build draft from factor positions</button><button id="copy-response">Copy comments</button><button data-edit="evaluation:${E(e.id)}">Record submission</button></div></div>`;
const after=`<div class="panel"><h2>Finalization and improvement</h2><p>Finalized: ${E(e.finalizationDate||'Awaiting Government finalization')}. Disposition: ${E(e.disposition||'Not recorded')}.</p><button data-edit="evaluation:${E(e.id)}" class="primary">Update finalization</button></div><div class="panel"><h2>Initial to final comparison</h2>${factorComparison(e)}</div><div class="panel"><h2>Improvement actions</h2><button data-new="action">Add action</button>${itemList(actions,x=>`${E(x.issue)} · ${E(x.department)} / ${E(x.owner)} · ${E(x.targetDate)} · ${E(x.status)}`,'action')}</div>`;
return `<p><a href="#evaluations">← All evaluations</a></p>${head(ename(e),`${E(c?.agency||'')} · ${E(e.periodStart)} to ${E(e.periodEnd)} · ${E(e.representative||c?.representative||'Unassigned')}`,`<button data-edit="evaluation:${E(e.id)}">Edit evaluation</button>`)}<section class="status-strip" aria-label="Evaluation status">${[['Government',e.governmentStatus||'Expected'],['Outreach',e.outreachStatus||'Not Started'],['Department inputs',e.readiness||'Not Started'],['Contractor response',e.responseStatus||'Not Started'],['Post actions',e.postStatus||'Not Started']].map(([k,v])=>`<div class="status-item"><small>${E(k)}</small>${chip(v)}</div>`).join('')}</section><div class="subnav">${[['before','Before CPARS'],['during','During CPARS'],['after','After CPARS']].map(([key,label])=>`<a href="#evaluations/${E(e.id)}/${key}" ${tab===key?'aria-current="page"':''}>${label}</a>`).join('')}</div>${tab==='during'?during:tab==='after'?after:before}<div class="panel"><h2>Government outreach history</h2>${itemList(outreach,x=>`${E(x.date)} · ${E(x.purpose)} · ${E(x.recipient)} · ${E(x.summary)}`,'outreach')}</div><div class="panel"><h2>Departmental readiness</h2><p>${assignments.filter(x=>x.status==='Complete').length} complete · ${assignments.filter(x=>x.dueDate&&x.dueDate<C.today()&&!['Complete','Not Applicable'].includes(x.status)).length} overdue · ${assignments.filter(x=>x.issues).length} with open questions</p>${itemList(assignments,x=>`${E(x.phase)} · ${E(x.department)} / ${E(x.owner)} · ${E(x.status)} · due ${E(x.dueDate)}`,'assignment')}</div><div class="panel"><div class="row"><h2>Subfactors</h2><button data-new="subfactor">Add subfactor</button></div>${itemList(state.subfactors.filter(x=>x.evaluationId===e.id),x=>`${E(x.factor)} / ${E(x.name)} · applicable: ${E(x.applicable||'Not sure')} · ${E(x.factStatus||'Not sure')}`,'subfactor')}</div><div class="panel"><div class="row"><h2>Internal reviews</h2><button data-new="review">Record review</button></div><p class="hint">User-maintained coordination record, not an authenticated approval.</p>${itemList(state.reviews.filter(x=>x.evaluationId===e.id),x=>`${E(x.phase)} · ${E(x.role)} / ${E(x.reviewer)} · ${E(x.status)} · ${E(x.date)}`,'review')}</div><div class="panel"><h2>Change history</h2>${itemList(e.history||[],x=>`${E(x.at)} · ${E(x.summary)}`)}</div>`;}
function itemList(list,label,type){return list.length?`<div class="stack">${list.map(x=>`<div class="item"><div class="row"><span>${label(x)}</span>${type?`<button data-edit="${type}:${E(x.id)}">Edit</button>`:''}</div></div>`).join('')}</div>`:'<p class="empty">No records yet.</p>';}
function factorEditor(e,mode){e.factors ||= {};return `<div class="stack">${C.FACTORS.map(f=>{const v=e.factors[f]||{};return `<details class="item"><summary><strong>${E(f)}</strong> · ${E(v.initialRating||'Not recorded')}</summary><div class="fields"><label>Applicable<select data-factor="${E(f)}" data-field="applicable">${selectOptions(['Not sure','Yes','No'],v.applicable||'Not sure')}</select></label><label>Initial Government rating<select data-factor="${E(f)}" data-field="initialRating">${selectOptions(C.RATINGS,v.initialRating||'Not recorded')}</select></label>${mode==='during'?`<label>Final Government rating<select data-factor="${E(f)}" data-field="finalRating">${selectOptions(C.RATINGS,v.finalRating||'Not recorded')}</select></label><label>Fact status<select data-factor="${E(f)}" data-field="factStatus">${selectOptions(['Not sure','Verified fact','Unsupported assertion','Disputed statement','Outstanding question','Corrective action taken','Commitment pending approval'],v.factStatus||'Not sure')}</select></label>`:''}<label class="${mode==='during'?'':'wide'}">${mode==='pre'?'Accomplishments, milestones, concerns, benefits':'Government narrative / assertion'}<textarea data-factor="${E(f)}" data-field="${mode==='pre'?'preSummary':'governmentText'}">${E(mode==='pre'?(v.preSummary??v.governmentText):v.governmentText)}</textarea></label><label class="${mode==='during'?'':'wide'}">Contractor position and proposed response<textarea data-factor="${E(f)}" data-field="position">${E(v.position)}</textarea></label><label class="wide">Evidence / contractual references<textarea data-factor="${E(f)}" data-field="evidence">${E(v.evidence)}</textarea></label><label class="wide">Requested resolution / reviewer feedback<textarea data-factor="${E(f)}" data-field="review">${E(v.review)}</textarea></label></div></details>`;}).join('')}</div>`;}
function factorComparison(e){return table(['Factor','Initial','Final','Position / requested change'],[...C.FACTORS.map(f=>({...(e.factors?.[f]||{}),name:f})),...state.subfactors.filter(x=>x.evaluationId===e.id).map(x=>({...x,name:x.factor+' / '+x.name}))].map(v=>{const f=v.name;return `<tr><td>${E(f)}</td><td>${E(v.initialRating||'—')}</td><td>${E(v.finalRating||'—')}</td><td>${E(v.position||'—')}</td></tr>`;}).join(''));}
function outreachView(){let list=state.outreach.filter(x=>{const e=evaluation(x.evaluationId);return e&&(metric()?active(e)&&dashboardMatch(e):match(e))&&(!metric()||metric()==='followups'&&!!x.nextDate&&x.nextDate<=C.today())}).sort((a,b)=>(a.nextDate||'9999').localeCompare(b.nextDate||'9999'));return head('Government outreach','Record each contact and the next follow-up. Messages are never sent by this app.',`<button class="primary" data-new="outreach">Record outreach</button>`)+`<div class="panel">${filters()}${metricBanner('outreach','follow-ups due')}${table(['Evaluation','Date / purpose','Recipient / response','Next follow-up','Actions'],list.map(o=>`<tr><td>${E(ename(evaluation(o.evaluationId)))}</td><td>${E(o.date)}<br>${E(o.purpose)}</td><td>${E(o.recipient)}<br>${E(o.response)}</td><td>${E(o.nextDate)}<br>${E(due(o.nextDate))}</td><td><button data-edit="outreach:${E(o.id)}">Edit</button></td></tr>`).join(''))}</div><div class="panel"><h2>Editable correspondence starters</h2><select id="template-kind"><option>Initial proactive outreach</option><option>Evaluation status request</option><option>Follow-up request</option><option>Finalization confirmation</option></select><textarea id="template-text" aria-label="Editable correspondence template"></textarea><button id="copy-template">Copy text</button><p class="hint">Review recipient, facts, authorization, and agency requirements before sending outside this app.</p></div>`;}
function departments(){const list=state.assignments.filter(x=>{const e=evaluation(x.evaluationId);return e&&match(e)});const actions=state.actions.filter(x=>{const e=evaluation(x.evaluationId);return e&&(metric()?active(e)&&dashboardMatch(e):match(e))&&(!metric()||['actions','overdueActions'].includes(metric())&&!['Complete','Not Applicable'].includes(x.status)&&(metric()!=='overdueActions'||!!x.targetDate&&x.targetDate<C.today()))});return head('Departmental coordination','Assignments are user-maintained records; this app does not distribute tasks or authenticate approvals.',`<button class="primary" data-new="assignment">Add input request</button>`)+`<div class="panel"><h2>Contributions</h2>${filters()}${table(['Evaluation','Phase / factor','Department / owner','Due','Status / review','Actions'],list.map(x=>`<tr><td>${E(ename(evaluation(x.evaluationId)))}</td><td>${E(x.phase)}<br>${E(x.factor)}</td><td>${E(x.department)} / ${E(x.owner)}</td><td>${E(x.dueDate)}<br>${E(due(x.dueDate))}</td><td>${E(x.status)}<br>${E(x.review)}</td><td><button data-edit="assignment:${E(x.id)}">Edit</button></td></tr>`).join(''))}</div><div class="panel"><div class="row"><h2>Improvement actions</h2><button data-new="action">Add action</button></div>${metricBanner('departments',metric()==='overdueActions'?'overdue improvement actions':'open improvement actions')}${table(['Evaluation','Issue','Owner','Target','Status','Actions'],actions.map(x=>`<tr><td>${E(ename(evaluation(x.evaluationId)))}</td><td>${E(x.issue)}</td><td>${E(x.department)} / ${E(x.owner)}</td><td>${E(x.targetDate)}</td><td>${E(x.status)}</td><td><button data-edit="action:${E(x.id)}">Edit</button></td></tr>`).join(''))}</div>`;}
const templates={
'Initial proactive outreach':'Subject: Upcoming performance evaluation — [contract/order]\n\nHello [recipient],\n\nWe are coordinating internal performance information for the period ending [date]. Please confirm the anticipated evaluation schedule and appropriate Government contact. We can provide authorized factual inputs if helpful.\n\nThank you,\n[name]',
'Evaluation status request':'Subject: Evaluation status — [contract/order]\n\nHello [recipient],\n\nCould you confirm the status and expected availability of the performance evaluation for [period]? Please let us know if any action is needed from our team.\n\nThank you,\n[name]',
'Follow-up request':'Subject: Follow-up on evaluation — [contract/order]\n\nHello [recipient],\n\nFollowing up on our [date] inquiry about the evaluation for [period]. Please advise on the current status and expected next step.\n\nThank you,\n[name]',
'Finalization confirmation':'Subject: Evaluation finalization — [contract/order]\n\nHello [recipient],\n\nPlease confirm whether the evaluation for [period] has been finalized and whether any further contractor action is requested.\n\nThank you,\n[name]'};
const reportNames={summary:'Management-safe portfolio summary',accountability:'Contracts representative accountability',expected:'Expected and outstanding evaluations',outreach:'Government outreach history',inputRequest:'Departmental performance input request',departments:'Departmental coordination status',narrative:'Pre-evaluation performance narrative',response:'Evaluation review and response worksheet',comparison:'Initial-to-final comparison',actions:'Improvement action plan'};
function reportRows(kind){const evals=state.evaluations.filter(match),byId=id=>evaluation(id);
if(kind==='accountability'){const headers=['Contracts representative','Open evaluations','Before CPARS','During CPARS','Awaiting finalization','Completed','Open department inputs','Open improvement actions'];const reps=[...new Set(evals.map(e=>e.representative||contract(e.contractId)?.representative||'Unassigned'))].sort();return {headers,rows:reps.map(rep=>{const owned=evals.filter(e=>(e.representative||contract(e.contractId)?.representative||'Unassigned')===rep),ids=new Set(owned.map(e=>e.id));return {'Contracts representative':rep,'Open evaluations':owned.filter(e=>!e.finalizationDate).length,'Before CPARS':owned.filter(e=>phase(e)==='Before CPARS').length,'During CPARS':owned.filter(e=>phase(e)==='During CPARS').length,'Awaiting finalization':owned.filter(e=>e.submissionDate&&!e.finalizationDate).length,Completed:owned.filter(e=>e.finalizationDate).length,'Open department inputs':state.assignments.filter(x=>ids.has(x.evaluationId)&&!['Complete','Not Applicable'].includes(x.status)).length,'Open improvement actions':state.actions.filter(x=>ids.has(x.evaluationId)&&!['Complete','Not Applicable'].includes(x.status)).length};})};}
if(kind==='expected'){const headers=['Contract / order','Contracts representative','Evaluation type','Evaluation period','Phase','Expected availability','Government completion target','Timing authority','Comment deadline','Next action'];return {headers,rows:evals.filter(e=>!e.finalizationDate).sort((a,b)=>(a.expectedAvailability||a.periodEnd||'').localeCompare(b.expectedAvailability||b.periodEnd||'')).map(e=>{const c=contract(e.contractId)||{};return {'Contract / order':cname(c),'Contracts representative':e.representative||c.representative,'Evaluation type':e.type,'Evaluation period':`${e.periodStart} to ${e.periodEnd}`,Phase:phase(e),'Expected availability':e.expectedAvailability,'Government completion target':e.reportingDeadline,'Timing authority':e.deadlineAuthority||'CPARS Guidance §4.8 target (verify)','Comment deadline':e.commentDeadline,'Next action':e.submissionDate?'Follow up on Government finalization':e.notificationDate?'Prepare contractor response':e.expectedAvailability&&e.expectedAvailability<C.today()?'Check delayed evaluation and outreach':'Confirm expected evaluation timing'};})};}
if(kind==='inputRequest'){const headers=['Contract / order','Evaluation period','Contracts representative','Phase','Factor','Department','Owner','Requested contribution','Assigned','Due','Status','Evidence reference'];return {headers,rows:state.assignments.filter(x=>evals.some(e=>e.id===x.evaluationId)).map(x=>{const e=byId(x.evaluationId),c=contract(e.contractId)||{};return {'Contract / order':cname(c),'Evaluation period':`${e.periodStart} to ${e.periodEnd}`,'Contracts representative':e.representative||c.representative,Phase:x.phase,Factor:x.factor,Department:x.department,Owner:x.owner,'Requested contribution':x.request,Assigned:x.assignedDate,Due:x.dueDate,Status:x.status,'Evidence reference':x.evidence};})};}if(kind==='outreach')return {headers:['Contract / order','Evaluation period','Date','Purpose','Recipient','Summary','Response','Next follow-up'],rows:state.outreach.filter(x=>evals.some(e=>e.id===x.evaluationId)).map(x=>{const e=byId(x.evaluationId);return {'Contract / order':cname(contract(e.contractId)),'Evaluation period':`${e.periodStart} to ${e.periodEnd}`,Date:x.date,Purpose:x.purpose,Recipient:x.recipient,Summary:x.summary,Response:x.response,'Next follow-up':x.nextDate};})};if(kind==='departments')return {headers:['Contract / order','Evaluation period','Phase','Department','Owner','Requested input','Due','Status','Contracts review'],rows:state.assignments.filter(x=>evals.some(e=>e.id===x.evaluationId)).map(x=>{const e=byId(x.evaluationId);return {'Contract / order':cname(contract(e.contractId)),'Evaluation period':`${e.periodStart} to ${e.periodEnd}`,Phase:x.phase,Department:x.department,Owner:x.owner,'Requested input':x.request,Due:x.dueDate,Status:x.status,'Contracts review':x.review};})};if(kind==='actions')return {headers:['Contract / order','Evaluation period','Issue','Department','Owner','Target','Status','Effectiveness'],rows:state.actions.filter(x=>evals.some(e=>e.id===x.evaluationId)).map(x=>{const e=byId(x.evaluationId);return {'Contract / order':cname(contract(e.contractId)),'Evaluation period':`${e.periodStart} to ${e.periodEnd}`,Issue:x.issue,Department:x.department,Owner:x.owner,Target:x.targetDate,Status:x.status,Effectiveness:x.effectiveness};})};if(kind==='narrative'||kind==='response'||kind==='comparison'){const rows=evals.flatMap(e=>[...C.FACTORS.map(f=>({...(e.factors?.[f]||{}),name:f})),...state.subfactors.filter(x=>x.evaluationId===e.id).map(x=>({...x,name:x.factor+' / '+x.name}))].map(v=>{const f=v.name;return {'Contract / order':cname(contract(e.contractId)),'Evaluation period':`${e.periodStart} to ${e.periodEnd}`,Factor:f,'Initial rating':v.initialRating,'Final rating':v.finalRating,'Government narrative / accomplishments':kind==='narrative'?(v.preSummary??v.governmentText):v.governmentText,'Contractor position':v.position,'Evidence reference':v.evidence,'Review / requested resolution':v.review};}));let headers=Object.keys(rows[0]||{'Contract / order':'','Evaluation period':'',Factor:''});if(kind==='narrative')headers=headers.filter(x=>!['Initial rating','Final rating'].includes(x));if(kind==='comparison')headers=headers.filter(x=>!['Government narrative / accomplishments','Evidence reference','Review / requested resolution'].includes(x));return {headers,rows};}const headers=['Contract / order','Agency','Contracts representative','Evaluation type','Evaluation period','Phase','Government status','Outreach status','Department readiness','Contractor response','Expected availability','Government completion target','Comment deadline','Finalization'];const rows=evals.map(e=>{const c=contract(e.contractId)||{};return {'Contract / order':cname(c),Agency:c.agency,'Contracts representative':e.representative||c.representative,'Evaluation type':e.type,'Evaluation period':`${e.periodStart} to ${e.periodEnd}`,Phase:phase(e),'Government status':e.governmentStatus,'Outreach status':e.outreachStatus,'Department readiness':e.readiness,'Contractor response':e.responseStatus,'Expected availability':e.expectedAvailability,'Government completion target':e.reportingDeadline,'Comment deadline':e.commentDeadline,Finalization:e.finalizationDate};});return {headers,rows};}
function reportHtml(){const data=reportRows(reportKind);const safe=reportKind==='summary';const headers=safe?data.headers.filter(x=>!['Comment deadline'].includes(x)):data.headers;const scoped=state.evaluations.filter(match),ids=new Set(scoped.map(x=>x.id)),reps=[...new Set(scoped.map(x=>x.representative||contract(x.contractId)?.representative||'Unassigned'))],openActions=state.actions.filter(x=>ids.has(x.evaluationId)&&!['Complete','Not Applicable'].includes(x.status)).length;const overview=safe?`<div class="report-overview"><strong>${scoped.length} evaluations</strong><strong>${scoped.filter(x=>x.notificationDate&&!x.finalizationDate).length} active comment/finalization records</strong><strong>${openActions} open improvement actions</strong></div>`:'';return `<div class="report"><h1>${E(reportNames[reportKind])}</h1><p>Prepared ${E(C.today())} · CPARS Coordination Tracker · Built by Courtney</p><p>Report status: Working coordination record. Verify dates and information in official CPARS. ${safe?'Detailed Government narratives and evaluation content excluded.':''}</p><p>Scope: ${scoped.length} evaluation(s) · Contracts representatives: ${E(reps.join(', ')||'None')} · Open improvement actions: ${openActions} · Timing authority: FAR 42.1502(a), FAR 42.1503(d), and CPARS Guidance §4.8, subject to documented overrides.</p>${overview}${table(headers,data.rows.map(row=>`<tr${headers.some(h=>String(row[h]??'').length>350)?' class="long-print"':''}>${headers.map(h=>`<td>${E(row[h]===0?'0':row[h]||'—')}</td>`).join('')}</tr>`).join(''))}<p>Timing: annual and completion evaluations—FAR 42.1502(a); 14-calendar-day initial comment window—FAR 42.1503(d); Government completion target—CPARS Guidance §4.8 (120 days), subject to verified agency requirements. Internal targets are planning dates.</p></div>`;}
function reports(){return head('Reports & data','Review every export before sharing. The summary omits detailed evaluation content.',`<button class="primary" id="print-report">Print / save PDF</button>`)+`<div class="panel report-controls"><label>Report<select id="report-kind">${Object.entries(reportNames).map(([k,v])=>`<option value="${k}" ${reportKind===k?'selected':''}>${E(v)}</option>`).join('')}</select></label>${filters()}<div class="actions"><button id="csv-report">Export filtered CSV</button><button id="backup">Download complete JSON backup</button></div></div><div id="report-preview">${reportHtml()}</div><div class="panel"><h2>Contract CSV import</h2><p>Reads text from the selected CSV locally. No upload or document inspection occurs. Duplicate contract/order keys are skipped.</p><div class="actions"><button id="template">Download CSV template</button><label>Choose CSV<input id="csv-input" type="file" accept=".csv,text/csv"></label></div><div id="import-preview"></div></div><div class="panel"><h2>Restore or clear</h2><p>Restore replaces all current browser records after confirmation. Export a backup first.</p><label>Choose JSON backup<input id="restore-input" type="file" accept=".json,application/json"></label><button id="clear-data" class="danger">Clear all local data</button></div>`;}
function settings(){return head('Settings & guide','Timing rules and handling limits.',`<button class="primary" id="save-settings">Save settings</button>`)+`<div class="panel"><h2>Fictional demonstration data</h2><div class="actions"><button id="load-sample">Load sample</button><button id="remove-sample" class="danger">Remove sample</button></div><p class="hint">Loading sample adds fictional records alongside your own. Removing sample leaves user-created records untouched.</p></div>`+`<div class="panel"><h2>Departments</h2><p class="hint">One department per line. These are suggestions; each assignment remains editable.</p><label>Department names<textarea id="department-settings">${E(state.settings.departments.join('\n'))}</textarea></label></div>`+`<div class="panel"><h2>Internal planning targets</h2><div class="fields">${[['availabilityDays','Expected availability: days after period end'],['internalResponseDays','Internal response: days after notification'],['advanceDays','Outreach: days before period end'],['followupDays','Follow-up interval in days'],['warningDays','Dashboard warning days']].map(([key,label])=>`<label>${label}<input type="number" min="1" max="365" data-setting="${key}" value="${E(state.settings[key])}"></label>`).join('')}</div><p class="hint">These targets are internal planning assumptions. They do not change FAR or CPARS guidance.</p></div><div class="panel"><h2>Regulatory references</h2><p>Verified 2026-11-25. <a href="https://www.acquisition.gov/far/42.1502" target="_blank" rel="noopener noreferrer">FAR 42.1502(a)</a> calls for at least annual and completion evaluations where applicable. <a href="https://www.acquisition.gov/far/42.1503" target="_blank" rel="noopener noreferrer">FAR 42.1503(d), (f)</a> governs the initial comment opportunity and later comments. <a href="https://www.cpars.gov/cparsweb/assets/documents/CPARS-Guidance.pdf" target="_blank" rel="noopener noreferrer">CPARS Guidance §4.8</a> states the entire evaluation process should be completed within 120 days after the performance period. This is guidance, not a separate FAR deadline. Confirm agency requirements and the official CPARS display.</p><p>The app never decides applicability from value alone. Order-level versus contract-level reporting and exceptions require user confirmation.</p></div><div class="panel"><h2>Data and workflow</h2><ol><li>Add a contract or order, set applicability, and confirm performance dates.</li><li>Review suggested cycles and add only the evaluations needed.</li><li>Record outreach and departmental input requests.</li><li>Enter the actual CPARS notification date to start the 14-calendar-day countdown; verify the displayed deadline.</li><li>Prepare and copy comments; submit only through official CPARS and record confirmation.</li><li>Record final ratings, finalization, and improvement actions.</li><li>Export reports and regular JSON backups.</li></ol><p>Browser-local storage is not encrypted, access controlled, or an approved handling environment by itself. Use only in an authorized environment. No network request carries entered data. External reference links open only when clicked. Dashboard indicators run while this page is open, including after the local date changes.</p></div>`;}
function render(){nav();const view=current();if(view==='evaluations'&&location.hash.split('/')[1])selected=location.hash.split('/')[1];$('#view').innerHTML=({dashboard,contracts,evaluations,outreach:outreachView,departments,reports,settings}[view]||dashboard)();if(view==='evaluations'&&selected&&location.hash.split('/')[1])$('#view').innerHTML=detail();if(view==='reports')$('#print-area').innerHTML=reportHtml();if(view==='outreach')$('#template-text').value=templates[$('#template-kind').value];}
function dialog(type,id){
  const record=id?state[collections[type]].find(x=>x.id===id):{};
  if(!record)return;
  const e=type==='evaluation'?record:evalForEntry(record);
  if(type!=='contract'&&type!=='evaluation'&&!e&&!state.evaluations.length){message('Add an evaluation first.');return;}
  $('#editor-title').textContent=(id?'Edit ':'Add ')+({assignment:'department input request',action:'improvement action',outreach:'Government outreach',contract:'contract or order',evaluation:'evaluation',review:'internal review',subfactor:'evaluation subfactor'}[type]||type);
  let fields='';
  if(type==='evaluation'&&!id){
    if(!state.contracts.length){message('Add a contract first.');return;}
    fields+=`<label class="wide">Contract or order<select name="contractId" required>${state.contracts.filter(c=>!c.archived).map(c=>`<option value="${E(c.id)}">${E(cname(c))}</option>`).join('')}</select></label>`;
  }
  if(['outreach','assignment','action','review','subfactor'].includes(type)&&!id)fields+=`<label class="wide">Evaluation<select name="evaluationId">${state.evaluations.filter(x=>!x.archived).map(x=>`<option value="${E(x.id)}" ${x.id===selected?'selected':''}>${E(ename(x))}</option>`).join('')}</select></label>`;
  const sections={
    contract:{contractNumber:['Contract or order','Identify the record and its owner.'],popStart:['Performance period','Enter dates used to suggest evaluation cycles.'],registration:['CPARS coordination','Confirm applicability and registration yourself.']},
    evaluation:{type:['Evaluation period','Confirm the type and dates before using suggested targets.'],expectedAvailability:['Timing','Planning targets and actual CPARS dates are separate.'],governmentStatus:['Coordination status','Track Government, department, and contractor progress independently.'],responseText:['Contractor response','Draft locally; submit only in official CPARS.'],finalizationDate:['Finalization','Record the Government result and any unresolved issues.']},
    outreach:{date:['Contact','Record what happened and who was involved.'],response:['Response and next step','Track commitments and follow-up.']},
    assignment:{phase:['Input request','Assign a department and due date.'],status:['Progress','Record the contribution and Contracts review.']},
    action:{issue:['Improvement action','Assign ownership and a target.'],status:['Progress and evidence','Record completion and effectiveness.']},
    review:{phase:['Internal review','User-entered coordination record; not an authenticated approval.']},
    subfactor:{factor:['Subfactor','Use a user-confirmed factor and applicability.']}
  };
  for(const [key,label,kind='text',required] of schema[type]){
    if(sections[type]?.[key]){const [title,help]=sections[type][key];fields+=`<div class="form-section-heading wide"><h3>${E(title)}</h3><p>${E(help)}</p></div>`;}
    const v=record[key]??(key==='applicability'||key==='reportingLevel'?'Pending Verification':key==='type'?'Annual':key==='governmentStatus'?'Expected':key==='responseStatus'?'Not Started':key==='status'?'Not Started':'');
    const attrs=`name="${key}" ${type==='assignment'&&key==='department'?'list="department-options"':''} ${required?'required':''}`;
    fields+=`<label class="${kind==='textarea'?'wide':''}">${E(label)}${required?' *':''}${kind==='textarea'?`<textarea ${attrs}>${E(v)}</textarea>`:kind==='checkbox'?`<input type="checkbox" ${attrs} ${v?'checked':''}>`:kind.startsWith('select:')?`<select ${attrs}>${selectOptions(kind.slice(7).split('|'),v)}</select>`:`<input type="${kind}" ${attrs} value="${E(v)}">`}</label>`;
  }
  if(type==='assignment')fields+=`<datalist id="department-options">${state.settings.departments.map(x=>`<option value="${E(x)}">`).join('')}</datalist>`;
  $('#editor-fields').innerHTML=fields;$('#editor-error').hidden=true;
  $('#editor-form').dataset.type=type;$('#editor-form').dataset.id=id||'';
  dialogReturnFocus=id?`[data-edit="${type}:${id}"]`:`[data-new="${type}"]`;
  $('#editor').showModal();$('#editor-fields input,#editor-fields select').focus();
}
function evalForEntry(r){return evaluation(r.evaluationId||selected);}
function uniqueKey(c){return [c.contractNumber,c.orderNumber].map(x=>String(x||'').trim().toUpperCase()).join('|');}
function recordSave(ev){
  ev.preventDefault();
  const form=ev.currentTarget,type=form.dataset.type,id=form.dataset.id;
  const data=Object.fromEntries(new FormData(form));
  for(const [key,,kind] of schema[type])if(kind==='checkbox')data[key]=form.elements[key].checked;
  const error=$('#editor-error');error.hidden=true;
  const fail=message=>{error.textContent=message;error.hidden=false;};
  if(type==='contract'&&state.contracts.some(c=>c.id!==id&&uniqueKey(c)===uniqueKey(data))){fail('A contract or order with this key already exists.');return;}
  if(type==='contract'&&data.reportingLevel==='Order'&&!data.orderNumber.trim()){fail('Enter an order number for order-level reporting.');return;}
  if(type==='evaluation'){
    const old=id?evaluation(id):null;
    const suggested=C.suggestedDates(data,state.settings);
    const previous=old?C.suggestedDates(old,state.settings):{};
    for(const k of ['expectedAvailability','reportingDeadline','commentDeadline','internalTarget']){
      if(!data[k]||(old&&old[k]===previous[k]&&data[k]===old[k]))data[k]=suggested[k];
    }
    if(!data.notificationDate)data.commentDeadline='';
    const issue=C.evaluationDateError(data);
    if(issue){fail(issue);return;}
    if(data.governmentStatus==='Finalized'&&!data.finalizationDate){fail('Enter a Government finalization date before marking the evaluation Finalized.');return;}
    if(data.reportingDeadline&&data.reportingDeadline!==suggested.reportingDeadline&&!data.deadlineAuthority.trim()){fail('Document the authority or reason for the Government deadline override.');return;}
    if(data.commentDeadline&&data.notificationDate&&data.commentDeadline!==suggested.commentDeadline&&!data.commentDeadlineNote.trim()){fail('Document the reason for the corrected CPARS comment deadline.');return;}
    if(!data.deadlineAuthority&&data.reportingDeadline===suggested.reportingDeadline)data.deadlineAuthority='CPARS Guidance §4.8 (120 calendar days after performance period)';
    if(data.notificationDate&&data.governmentStatus==='Expected')data.governmentStatus='Available for Comment';
    const tracked=['periodStart','periodEnd','expectedAvailability','reportingDeadline','deadlineAuthority','notificationDate','commentDeadline','commentDeadlineNote','internalTarget','submissionDate','finalizationDate','governmentStatus','responseStatus'];
    const changes=old?tracked.filter(k=>String(old[k]||'')!==String(data[k]||'')).map(k=>`${k}: ${old[k]||'—'} → ${data[k]||'—'}`):[];
    data.history=[...(old?.history||[]),{at:new Date().toISOString(),summary:id?(changes.length?changes.join('; '):'Evaluation edited'):'Evaluation created'}];
    data.factors=old?.factors||{};
  }
  const list=state[collections[type]];
  if(id)Object.assign(list.find(x=>x.id===id),data);
  else{data.id=C.uid();list.push(data);if(type==='evaluation')selected=data.id;}
  $('#editor').close();save();message(`${type[0].toUpperCase()+type.slice(1)} saved.`);
}
function reviewCycles(id){const c=contract(id),cycles=C.cycles(c);const existing=new Set(state.evaluations.filter(e=>e.contractId===id).map(e=>`${e.periodStart}|${e.periodEnd}`));if(c.reportingLevel==='Pending Verification'){message('Confirm contract-level or order-level reporting before creating evaluation periods.');return;}if(!cycles.length){message('Set applicability to Applicable and enter valid performance dates first.');return;}const missing=cycles.filter(x=>!existing.has(`${x.periodStart}|${x.periodEnd}`));if(!missing.length){message('All suggested periods already have evaluations.');return;}if(!confirm(`Add ${missing.length} suggested evaluation period(s) for ${cname(c)}? Confirm contract/order reporting level and schedule before continuing.`))return;for(const x of missing){const e={...x,id:C.uid(),contractId:id,governmentStatus:'Expected',outreachStatus:'Not Started',readiness:'Not Started',responseStatus:'Not Started',postStatus:'Not Started',representative:c.representative,history:[{at:new Date().toISOString(),summary:'Suggested cycle confirmed by user'}],factors:{}};Object.assign(e,C.suggestedDates(e,state.settings));state.evaluations.push(e);}save();message(`${missing.length} evaluation period(s) added. Review dates and type.`);location.hash='#evaluations';}
function download(name,content,mime){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importCsv(file){file.text().then(text=>{try{const rows=C.csvRows(text.replace(/^\uFEFF/,''));const headers=rows.shift().map(x=>x.trim());if(!headers.includes('contractNumber'))throw Error('CSV needs a contractNumber column.');const known=new Set(state.contracts.map(uniqueKey));const accepted=[],rejected=[];rows.forEach((cells,i)=>{if(cells.every(x=>!x.trim()))return;const obj=Object.fromEntries(headers.map((h,n)=>[h,cells[n]||'']));if(!obj.contractNumber?.trim()){rejected.push(`Row ${i+2}: missing contract number`);return;}const key=uniqueKey(obj);if(known.has(key)){rejected.push(`Row ${i+2}: duplicate contract/order`);return;}known.add(key);accepted.push({...obj,id:C.uid(),applicability:['Applicable','Not Applicable'].includes(obj.applicability)?obj.applicability:'Pending Verification',reportingLevel:['Contract','Order'].includes(obj.reportingLevel)?obj.reportingLevel:'Pending Verification',archived:false});});pendingImport=accepted;$('#import-preview').innerHTML=`<p>${accepted.length} ready; ${rejected.length} skipped.</p>${rejected.length?`<ul>${rejected.slice(0,12).map(x=>`<li>${E(x)}</li>`).join('')}</ul>`:''}${accepted.length?'<button id="confirm-import" class="primary">Import ready rows</button>':''}`;}catch(e){$('#import-preview').textContent=e.message;pendingImport=null;}});}
function restore(file){file.text().then(text=>{try{const data=C.normalizeState(JSON.parse(text));if(!confirm(`Replace all local data with ${data.contracts.length} contracts and ${data.evaluations.length} evaluations?`))return;state=data;selected='';save();message('Backup restored.');}catch(e){message('Restore failed: '+e.message);}});}
function sample(){if(!confirm('Add fictional sample records? Existing records remain.'))return;const c={id:C.uid(),contractNumber:'FICT-2026-001',nickname:'Harbor logistics',agency:'Example Civilian Agency',office:'Example Contracts Office',popStart:'2026-01-01',popEnd:'2027-12-31',representative:'Avery',manager:'Morgan',applicability:'Applicable',applicabilityRationale:'Fictional example; user confirmation required',registration:'Registered',reportingLevel:'Contract'};const e={id:C.uid(),contractId:c.id,type:'Annual',periodStart:'2026-01-01',periodEnd:'2026-12-31',governmentStatus:'Expected',outreachStatus:'Planned',readiness:'Requested',responseStatus:'Not Started',postStatus:'Not Started',representative:'Avery',sample:true,history:[],factors:{'Technical/Quality':{applicable:'Yes',governmentText:'Fictional milestone summary for demonstration only.'}}};Object.assign(e,C.suggestedDates(e,state.settings));c.sample=true;state.contracts.push(c);state.evaluations.push(e);state.assignments.push({id:C.uid(),evaluationId:e.id,phase:'Before CPARS',factor:'Technical/Quality',department:'Program Management',owner:'Morgan',request:'Provide fictional milestone summary',dueDate:'2026-12-10',status:'Requested',sample:true});state.outreach.push({id:C.uid(),evaluationId:e.id,date:'2026-11-20',representative:'Avery',recipient:'Example Government contact',method:'Email',purpose:'Confirm evaluation timing',summary:'Requested anticipated schedule.',nextDate:'2026-12-04',sample:true});state.actions.push({id:C.uid(),evaluationId:e.id,issue:'Fictional improvement follow-up',department:'Program Management',owner:'Morgan',targetDate:'2027-02-01',status:'Open',sample:true});e.postStatus='Open';e.factors['Technical/Quality'].initialRating='Satisfactory';save();message('Fictional sample added.');}
function removeSample(){const retained=C.removeSampleRecords(state);save();message(retained?`Fictional sample removed. ${retained} evaluation(s) with your records were retained.`:'Fictional sample removed.');}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.new){dialog(b.dataset.new);return;}if(b.dataset.edit){const [type,id]=b.dataset.edit.split(':');dialog(type,id);return;}if(b.dataset.cycle){reviewCycles(b.dataset.cycle);return;}if(b.dataset.open){location.hash=`#evaluations/${b.dataset.open}/${phaseTab(evaluation(b.dataset.open))}`;return;}if(b.id==='cancel-editor'){$('#editor').close();return;}if(b.id==='print-report'){$('#print-area').innerHTML=reportHtml();window.print();return;}if(b.id==='csv-report'){const d=reportRows(reportKind);download(`cpars-${reportKind}.csv`,C.csv(d.headers,d.rows),'text/csv;charset=utf-8');return;}if(b.id==='backup'){download('cpars-backup.json',JSON.stringify(state,null,2),'application/json');return;}if(b.id==='template'){download('cpars-contract-template.csv',C.csv(['contractNumber','orderNumber','parentContract','reportingLevel','nickname','agency','office','contractType','popStart','popEnd','representative','manager','applicability','applicabilityRationale'],[]),'text/csv;charset=utf-8');return;}if(b.id==='confirm-import'){state.contracts.push(...pendingImport);pendingImport=null;save();message('Contracts imported.');return;}if(b.id==='clear-data'){if(confirm('Delete all browser-local CPARS data? Export a backup first.')){state=defaults();selected='';save();message('Local data cleared.');}return;}if(b.id==='save-settings'){document.querySelectorAll('[data-setting]').forEach(x=>state.settings[x.dataset.setting]=Math.max(1,Math.min(365,Number(x.value)||1)));state.settings.departments=[...new Set($('#department-settings').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean))].slice(0,30);if(!state.settings.departments.length){message('Enter at least one department.');return;}save();message('Internal targets saved.');return;}if(b.id==='build-response'){const e=evaluation();const parts=C.FACTORS.map(f=>({name:f,...(e.factors?.[f]||{})})).filter(v=>v.position||v.review||v.evidence);if(!parts.length){message('Enter a contractor position, requested resolution, or evidence in a factor first.');return;}if(e.responseText&&!confirm('Replace the current draft with a new draft from the factor worksheet?'))return;e.responseText=parts.map(v=>`${v.name}
Position: ${v.position||'To be completed'}${v.evidence?`
Evidence: ${v.evidence}`:''}${v.review?`
Requested resolution: ${v.review}`:''}`).join('\n\n');save();message('Editable draft built from the factor worksheet. Review before use.');return;}if(b.id==='copy-response'){await navigator.clipboard.writeText($('#response-text').value);message('Comments copied.');return;}if(b.id==='copy-template'){await navigator.clipboard.writeText($('#template-text').value);message('Template copied.');return;}if(b.id==='load-sample')sample();if(b.id==='remove-sample')removeSample();});
document.addEventListener('change',ev=>{const x=ev.target;if(x.id==='report-kind'){reportKind=x.value;render();}if(x.id==='template-kind')$('#template-text').value=templates[x.value];if(x.id==='csv-input'&&x.files[0])importCsv(x.files[0]);if(x.id==='restore-input'&&x.files[0])restore(x.files[0]);if(x.dataset.factor){const e=evaluation();e.factors ||= {};e.factors[x.dataset.factor] ||= {};e.factors[x.dataset.factor][x.dataset.field]=x.value;clearTimeout(saveTimer);saveTimer=setTimeout(persist,100);if(x.dataset.field==='initialRating'){const label=x.closest('details')?.querySelector('summary strong');if(label)label.parentNode.lastChild.textContent=` · ${x.value}`;}}});
document.addEventListener('input',ev=>{const x=ev.target;if(x.id==='search'){filter=x.value;const pos=x.selectionStart;render();const y=$('#search');y.focus();y.setSelectionRange(pos,pos);}if(x.id==='response-text'){const e=evaluation();if(e){e.responseText=x.value;clearTimeout(saveTimer);saveTimer=setTimeout(persist,300);}}if(x.dataset.factor&&x.tagName==='TEXTAREA'){const e=evaluation();e.factors ||= {};e.factors[x.dataset.factor] ||= {};e.factors[x.dataset.factor][x.dataset.field]=x.value;clearTimeout(saveTimer);saveTimer=setTimeout(persist,300);}});
document.addEventListener('change',ev=>{if(ev.target.id==='rep-filter'){repFilter=ev.target.value;render();}if(ev.target.dataset.dashboardFilter){dash[ev.target.dataset.dashboardFilter]=ev.target.value;render();}});
$('#editor-form').addEventListener('submit',recordSave);$('#editor').addEventListener('close',()=>requestAnimationFrame(()=>{(document.querySelector(dialogReturnFocus)||$('#main')).focus();}));window.addEventListener('hashchange',()=>{render();$('#main').focus();});let lastDate=C.today();setInterval(()=>{if(C.today()!==lastDate){lastDate=C.today();render();message('Date changed; indicators recalculated.');}},60000);
window.addEventListener('pagehide',()=>{if(saveTimer){clearTimeout(saveTimer);persist();}});load().then(()=>{syncStatuses();if(!location.hash)location.hash='#dashboard';render();});
})();
